import React, { useEffect, useState } from "react";

const getMovesetPath = (battleMode) =>
    battleMode === "singles"
        ? "/singles/csv_movesets/"
        : "/doubles/csv_movesets/";

export default function PokemonBuildPanel({
    clickedBuild,
    battleMode,
}) {
    const [buildData, setBuildData] = useState(null);
    const [imgSrc, setImgSrc] = useState(null);

    const [tooltip, setTooltip] = useState(null);
    const [cache, setCache] = useState({});

    const MOVESET_PATH = getMovesetPath(battleMode);

    const normalize = (name) =>
        name
            ?.toLowerCase()
            .replace(/[^a-z0-9\s-]/g, "")
            .trim()
            .replace(/\s+/g, "-");

    const resolveImage = (name) =>
        `/pokemon_artwork/${normalize(name)}.jpg`;

    const handleImgError = (e, name) => {
        const base = `/pokemon_artwork/${normalize(name)}`;
        if (e.target.src.endsWith(".jpg")) {
            e.target.src = `${base}.png`;
        } else {
            e.target.style.display = "none";
        }
    };

    const loadCSV = async (path) => {
        const res = await fetch(path);
        return await res.text();
    };

    const parseCSV = (text) =>
        text
            .trim()
            .split(/\r?\n/)
            .slice(1)
            .map((r) =>
                r.split(/,(?=(?:(?:[^"]*"){2})*[^"]*$)/)
            );

    // 🔥 FETCH INFO (FIXED)
    const fetchInfo = async (name, category) => {
        const key = `${category}-${name}`;
        if (cache[key]) return cache[key];

        let url = "";

        if (category === "Moves")
            url = `https://pokeapi.co/api/v2/move/${normalize(name)}`;
        else if (category === "Abilities")
            url = `https://pokeapi.co/api/v2/ability/${normalize(name)}`;
        else if (category === "Items")
            url = `https://pokeapi.co/api/v2/item/${normalize(name)}`;
        else if (category === "Natures")
            url = `https://pokeapi.co/api/v2/nature/${normalize(name)}`;
        else return null;

        try {
            const res = await fetch(url);
            const data = await res.json();

            let info = "No description";

            // ✅ MOVES
            if (category === "Moves") {
                const entry = data.effect_entries?.find(
                    (e) => e.language.name === "en"
                );

                const flavor = data.flavor_text_entries?.find(
                    (e) => e.language.name === "en"
                );

                info =
                    entry?.short_effect ||
                    entry?.effect ||
                    flavor?.flavor_text;
            }

            // ✅ ABILITIES
            else if (category === "Abilities") {
                const entry = data.effect_entries?.find(
                    (e) => e.language.name === "en"
                );
                info = entry?.short_effect || entry?.effect;
            }

            // ✅ ITEMS
            else if (category === "Items") {
                const entry = data.effect_entries?.find(
                    (e) => e.language.name === "en"
                );
                info = entry?.short_effect || entry?.effect;
            }

            // ✅ NATURES
            else if (category === "Natures") {
                const formatStat = (s) =>
                    s?.name
                        ?.replace("special-attack", "SP. ATK")
                        .replace("special-defense", "SP. DEF")
                        .replace("-", " ")
                        .toUpperCase();

                info = `Boosts ${formatStat(
                    data.increased_stat
                )}, lowers ${formatStat(
                    data.decreased_stat
                )}`;
            }

            const cleaned = info?.replace(/\n|\f/g, " ");

            setCache((prev) => ({
                ...prev,
                [key]: cleaned,
            }));

            return cleaned;
        } catch (err) {
            return "No data found";
        }
    };

    useEffect(() => {
        if (!clickedBuild || !clickedBuild.sourceFile) {
            setBuildData(null);
            return;
        }

        const loadBuild = async () => {
            const text = await loadCSV(
                MOVESET_PATH + clickedBuild.sourceFile
            );

            const rows = parseCSV(text);

            const pokemonRows = rows.filter(
                (r) =>
                    normalize(r[1]) ===
                    normalize(clickedBuild.pokemon)
            );

            const grouped = {};

            for (let row of pokemonRows) {
                const category = row[2];

                const itemName =
                    category === "Stats"
                        ? row[3]
                        : row[4];

                const usage = row[5];

                // ❌ skip unwanted stats
                if (
                    category === "Stats" &&
                    [
                        "Raw count",
                        "Avg. weight",
                        "Viability Ceiling",
                    ].includes(itemName)
                )
                    continue;

                // 🔥 HANDLE SPREADS → NATURES
                if (category === "Spreads") {
                    const spread = row[4]; // "Jolly:252/252/..."

                    const nature = spread?.split(":")[0];

                    if (nature) {
                        if (!grouped["Natures"]) {
                            grouped["Natures"] = [];
                        }

                        grouped["Natures"].push({
                            name: nature,
                            usage,
                        });
                    }

                    continue;
                }

                if (!itemName) continue;

                if (!grouped[category]) {
                    grouped[category] = [];
                }

                grouped[category].push({
                    name: itemName,
                    usage,
                });
            }

            // sort + top 5
            Object.keys(grouped).forEach((cat) => {
                grouped[cat] = grouped[cat]
                    .sort(
                        (a, b) =>
                            Number(b.usage) - Number(a.usage)
                    )
                    .slice(0, 5);
            });

            setImgSrc(resolveImage(clickedBuild.display));

            setBuildData({
                display: clickedBuild.display,
                month: clickedBuild.month,
                data: grouped,
            });
        };

        loadBuild();
    }, [clickedBuild, MOVESET_PATH]);

    if (!buildData) {
        return (
            <div style={{ padding: "10px" }}>
                Click a graph point to view build
            </div>
        );
    }

    return (
        <div
            style={{
                height: "600px",
                overflowY: "auto",
                border: "1px solid #ccc",
                borderRadius: "10px",
                padding: "12px",
                background: "#fafafa",
                position: "relative",
            }}
        >
            <img
                src={imgSrc}
                alt={buildData.display}
                onError={(e) =>
                    handleImgError(e, buildData.display)
                }
                style={{
                    width: "110px",
                    display: "block",
                    margin: "0 auto 10px",
                }}
            />

            <h3 style={{ textAlign: "center" }}>
                {buildData.display} — {buildData.month}
            </h3>

            <div>
                {Object.entries(buildData.data).map(
                    ([category, items]) => (
                        <div key={category}>
                            <strong>{category}</strong>
                            <ul>
                                {items.map((item, idx) => (
                                    <li
                                        key={idx}
                                        onMouseEnter={async (e) => {
                                            if (
                                                ![
                                                    "Moves",
                                                    "Abilities",
                                                    "Items",
                                                    "Natures",
                                                ].includes(category)
                                            )
                                                return;

                                            const info =
                                                await fetchInfo(
                                                    item.name,
                                                    category
                                                );

                                            setTooltip({
                                                text: info,
                                                x: e.clientX,
                                                y: e.clientY,
                                            });
                                        }}
                                        onMouseLeave={() =>
                                            setTooltip(null)
                                        }
                                        style={{
                                            cursor: [
                                                "Moves",
                                                "Abilities",
                                                "Items",
                                                "Natures",
                                            ].includes(category)
                                                ? "pointer"
                                                : "default",
                                        }}
                                    >
                                        {item.name} ({item.usage}%)
                                    </li>
                                ))}
                            </ul>
                        </div>
                    )
                )}
            </div>

            {/* 🔥 TOOLTIP */}
            {tooltip && (
                <div
                    style={{
                        position: "fixed",
                        top: tooltip.y + 10,
                        left: tooltip.x + 10,
                        background: "#222",
                        color: "#fff",
                        padding: "8px",
                        borderRadius: "6px",
                        maxWidth: "300px",
                        fontSize: "12px",
                        zIndex: 9999,
                    }}
                >
                    {tooltip.text}
                </div>
            )}
        </div>
    );
}
